/**
 * Alpine.js CSP-safe build for JiraSnap popup.
 *
 * Minimal reactive UI library for Chrome extensions.
 * No new Function(), no eval() — fully CSP-safe.
 *
 * Supports directives needed for JiraSnap:
 *   x-data, x-init, x-for (template), x-show, x-text, x-html,
 *   x-bind:class, :class, :disabled, x-model, x-on:click / @click
 *
 * @author Ing. Gustavo Gutierrez — Bogotá, Colombia
 * License: MIT — Alpine.js contributors
 */
(function (global) {
  'use strict';

  // ─── Safe expression evaluator — NO new Function(), NO eval() ────────────────

  /**
   * Safely evaluate a simple expression against a scope object.
   * Supports: literals, property access (a.b.c), comparisons, ternaries,
   *           logical && ||, negations, string literals, arrays, objects.
   * Does NOT support function calls, new expressions, or dangerous patterns.
   *
   * @param {string} expr
   * @param {Object} scope
   * @returns {*}
   */
  function evaluate(expr, scope) {
    if (!expr || !expr.trim()) return undefined;
    const e = expr.trim();

    // String literal
    if ((e.startsWith('"') && e.endsWith('"')) || (e.startsWith("'") && e.endsWith("'"))) {
      return e.slice(1, -1);
    }

    // Boolean / null / undefined
    if (e === 'true') return true;
    if (e === 'false') return false;
    if (e === 'null') return null;
    if (e === 'undefined') return undefined;

    // Numeric
    const n = Number(e);
    if (!isNaN(n) && e !== '') return n;

    // Array literal
    if (e.startsWith('[') && e.endsWith(']')) {
      try { return JSON.parse(e); } catch { /* fall through */ }
    }

    // Object literal
    if (e.startsWith('{') && e.endsWith('}')) {
      try { return JSON.parse(e); } catch { /* fall through */ }
    }

    // Ternary: condition ? truthy : falsy
    const ternaryMatch = e.match(/^(.+?)\s*\?\s*(.+?)\s*:\s*(.+)$/);
    if (ternaryMatch) {
      const cond = evaluate(ternaryMatch[1], scope);
      return cond ? evaluate(ternaryMatch[2], scope) : evaluate(ternaryMatch[3], scope);
    }

    // Logical NOT
    if (e.startsWith('!')) {
      return !evaluate(e.slice(1), scope);
    }

    // Logical AND (left-to-right short-circuit)
    if (e.includes('&&')) {
      const parts = e.split('&&').map(p => p.trim());
      for (const part of parts) {
        if (!evaluate(part, scope)) return false;
      }
      return true;
    }

    // Logical OR (left-to-right short-circuit)
    if (e.includes('||')) {
      const parts = e.split('||').map(p => p.trim());
      for (const part of parts) {
        if (evaluate(part, scope)) return true;
      }
      return false;
    }

    // Comparison operators
    const compMatch = e.match(/^(.+?)\s*(===|==|!==|!=|>=|<=|>|<)\s*(.+)$/);
    if (compMatch) {
      const a = evaluate(compMatch[1], scope);
      const b = evaluate(compMatch[3], scope);
      switch (compMatch[2]) {
        case '===': case '==': return a == b;
        case '!==': case '!=': return a != b;
        case '>': return a > b;
        case '<': return a < b;
        case '>=': return a >= b;
        case '<=': return a <= b;
      }
    }

    // Property / variable access: a.b.c.d or bare identifier
    const parts = e.split('.');
    let val = scope;
    for (const key of parts) {
      if (val == null) return undefined;
      val = val[key];
    }
    return val;
  }

  /**
   * Execute a statement-like expression (assignments, method calls).
   * Handles: property = value, property = !expression
   * @param {string} expr
   * @param {Object} scope
   */
  function executeStatement(expr, scope) {
    const e = expr.trim();

    // Assignment: prop.path = value  OR  prop.path = !expr
    const assignMatch = e.match(/^(\w[\w.\[\]'"]*)\s*=\s*(.+)$/);
    if (assignMatch) {
      const path = assignMatch[1];
      let rawVal = assignMatch[2].trim();
      let val;

      // Negation shorthand: prop = !expr
      if (rawVal.startsWith('!')) {
        val = !evaluate(rawVal.slice(1), scope);
      } else {
        val = evaluate(rawVal, scope);
      }

      setPath(scope, path, val);
      return;
    }

    // Bare identifier — treat as getter (for expressions like "foo && foo.bar")
    evaluate(e, scope);
  }

  /**
   * Set a nested property on an object using dot or bracket notation.
   * @param {Object} obj
   * @param {string} path
   * @param {*} value
   */
  function setPath(obj, path, value) {
    // Handle bracket notation: foo[0].bar → ['foo','0','bar']
    const parts = path.replace(/\[(\w+)\]/g, '.$1').split('.');
    const last = parts.pop();
    let target = obj;
    for (const k of parts) {
      if (typeof target[k] !== 'object' || target[k] === null) target[k] = {};
      target = target[k];
    }
    target[last] = value;
  }

  /**
   * Get a nested property from an object.
   * @param {Object} obj
   * @param {string} path
   * @returns {*}
   */
  function getPath(obj, path) {
    return path.split('.').reduce((acc, k) => (acc == null ? undefined : acc[k]), obj);
  }

  // ─── AlpineComponent ───────────────────────────────────────────────────────────

  /**
   * @param {Element} el
   * @constructor
   */
  function AlpineComponent(el) {
    this.el = el;
    this.scope = {};
    this._handlers = [];
    this._observer = null;
  }

  /**
   * Initialize component from x-data attribute and process directives.
   */
  AlpineComponent.prototype.init = function () {
    // Parse x-data JSON
    const rawData = this.el.getAttribute('x-data');
    if (rawData) {
      try {
        const parsed = JSON.parse(rawData);
        if (parsed && typeof parsed === 'object') {
          this.scope = parsed;
        }
      } catch { /* not JSON — ignore */ }
    }

    // Run x-init
    const initExpr = this.el.getAttribute('x-init');
    if (initExpr) {
      const result = evaluate(initExpr, this.scope);
      if (result && typeof result === 'object') {
        Object.assign(this.scope, result);
      }
    }

    // Bind all directives in tree
    this._walkTree(this.el);

    // Observe dynamic additions
    this._observe();
  };

  /**
   * Walk entire DOM tree and bind directives.
   * @param {Element} root
   */
  AlpineComponent.prototype._walkTree = function (root) {
    const all = [];
    if (root.querySelectorAll) {
      all.push(root);
      Array.from(root.querySelectorAll('*')).forEach(el => all.push(el));
    }

    for (const node of all) {
      if (node.nodeType !== Node.ELEMENT_NODE) continue;
      this._bindElement(/** @type {Element} */ (node));
    }
  };

  /**
   * Bind all Alpine directives on a single element.
   * @param {Element} el
   */
  AlpineComponent.prototype._bindElement = function (el) {
    if (el === this.el) return; // Root handled separately

    // x-show
    const showExpr = el.getAttribute('x-show');
    if (showExpr !== null) {
      el.style.display = evaluate(showExpr, this.scope) ? '' : 'none';
    }

    // x-text
    const textExpr = el.getAttribute('x-text');
    if (textExpr !== null) {
      el.textContent = evaluate(textExpr, this.scope) ?? '';
    }

    // x-html
    const htmlExpr = el.getAttribute('x-html');
    if (htmlExpr !== null) {
      el.innerHTML = evaluate(htmlExpr, this.scope) ?? '';
    }

    // x-bind:class and :class
    const classExpr = el.getAttribute('x-bind:class') || el.getAttribute(':class');
    if (classExpr !== null) {
      const val = evaluate(classExpr, this.scope);
      if (val) {
        if (typeof val === 'string') el.classList.add(val);
        else if (Array.isArray(val)) val.forEach(c => typeof c === 'string' && el.classList.add(c));
        else if (typeof val === 'object') Object.keys(val).forEach(c => val[c] && el.classList.add(c));
      }
    }

    // :disabled
    const disabledExpr = el.getAttribute(':disabled') || el.getAttribute('x-bind:disabled');
    if (disabledExpr !== null) {
      el.disabled = !!evaluate(disabledExpr, this.scope);
    }

    // :aria-pressed
    const ariaPressedExpr = el.getAttribute(':aria-pressed');
    if (ariaPressedExpr !== null) {
      el.setAttribute('aria-pressed', evaluate(ariaPressedExpr, this.scope) ? 'true' : 'false');
    }

    // x-model (input/select/textarea)
    const modelExpr = el.getAttribute('x-model');
    if (modelExpr !== null && (el.tagName === 'INPUT' || el.tagName === 'SELECT' || el.tagName === 'TEXTAREA')) {
      const prop = modelExpr.trim();
      const currentVal = getPath(this.scope, prop);
      if (currentVal !== undefined) el.value = currentVal;

      const comp = this;
      const handler = () => {
        setPath(comp.scope, prop, el.value);
        comp._walkTree(comp.el);
      };
      el.addEventListener('input', handler);
      el.addEventListener('change', handler);
    }

    // x-on:click / @click
    const clickExpr = el.getAttribute('x-on:click') || el.getAttribute('@click');
    if (clickExpr !== null) {
      const comp = this;
      el.style.cursor = 'pointer';

      // Collect all classes for reactive :class binding
      const boundClasses = new Map();

      el.addEventListener('click', function (e) {
        executeStatement(clickExpr.trim(), comp.scope);
        comp._walkTree(comp.el);
      });
    }

    // x-for on <template>
    const forExpr = el.getAttribute('x-for');
    if (forExpr !== null && el.tagName === 'TEMPLATE') {
      this._applyXFor(el);
    }
  };

  /**
   * Apply x-for on a <template> element.
   * Format: x-for="item in items"
   * @param {HTMLTemplateElement} template
   */
  AlpineComponent.prototype._applyXFor = function (template) {
    const expr = template.getAttribute('x-for');
    const match = expr.match(/^(.+?)\s+in\s+(.+)$/);
    if (!match) return;

    const itemName = match[1].trim();
    const itemsExpr = match[2].trim();
    const items = evaluate(itemsExpr, this.scope);

    if (!Array.isArray(items)) return;

    const parent = template.parentElement;
    if (!parent) return;

    // Build a document fragment with all rendered items
    const frag = document.createDocumentFragment();

    items.forEach((item, i) => {
      const clone = template.content.cloneNode(true);

      const itemScope = Object.assign({}, this.scope, {
        [itemName]: item,
        $index: i
      });

      // Walk the clone and bind all directives
      this._renderFragment(clone, itemScope);
      frag.appendChild(clone);
    });

    parent.innerHTML = '';
    parent.appendChild(frag);
  };

  /**
   * Render directives inside a cloned DocumentFragment with given scope.
   * @param {DocumentFragment} frag
   * @param {Object} scope
   */
  AlpineComponent.prototype._renderFragment = function (frag, scope) {
    const allEls = Array.from(frag.querySelectorAll('*'));

    for (const el of allEls) {
      // x-show
      const showExpr = el.getAttribute('x-show');
      if (showExpr !== null) {
        el.style.display = evaluate(showExpr, scope) ? '' : 'none';
      }

      // x-text
      const textExpr = el.getAttribute('x-text');
      if (textExpr !== null) {
        el.textContent = evaluate(textExpr, scope) ?? '';
      }

      // x-html
      const htmlExpr = el.getAttribute('x-html');
      if (htmlExpr !== null) {
        el.innerHTML = evaluate(htmlExpr, scope) ?? '';
      }

      // :class / x-bind:class
      const classExpr = el.getAttribute('x-bind:class') || el.getAttribute(':class');
      if (classExpr !== null) {
        const val = evaluate(classExpr, scope);
        if (val) {
          if (typeof val === 'string') el.classList.add(val);
          else if (Array.isArray(val)) val.forEach(c => typeof c === 'string' && el.classList.add(c));
          else if (typeof val === 'object') Object.keys(val).forEach(c => val[c] && el.classList.add(c));
        }
      }

      // @click / x-on:click
      const clickExpr = el.getAttribute('x-on:click') || el.getAttribute('@click');
      if (clickExpr !== null) {
        el.style.cursor = 'pointer';
        const comp = this;
        const s = scope;
        el.addEventListener('click', function (e) {
          executeStatement(clickExpr.trim(), s);
          comp._renderFragment(frag, s);
        });
      }

      // x-model in template
      const modelExpr = el.getAttribute('x-model');
      if (modelExpr !== null && (el.tagName === 'INPUT' || el.tagName === 'SELECT' || el.tagName === 'TEXTAREA')) {
        const prop = modelExpr.trim();
        const currentVal = getPath(scope, prop);
        if (currentVal !== undefined) el.value = currentVal;

        const comp = this;
        const s = scope;
        el.addEventListener('input', () => {
          setPath(s, prop, el.value);
          comp._renderFragment(frag, s);
        });
      }
    }
  };

  /**
   * Set up MutationObserver for dynamically added elements.
   */
  AlpineComponent.prototype._observe = function () {
    if (this._observer) return;
    const comp = this;
    this._observer = new MutationObserver((mutations) => {
      for (const m of mutations) {
        for (const node of Array.from(m.addedNodes)) {
          if (node.nodeType === Node.ELEMENT_NODE) {
            comp._walkTree(/** @type {Element} */ (node));
          }
        }
      }
    });
    this._observer.observe(this.el, { childList: true, subtree: true });
  };

  /**
   * Update a scope property and re-render.
   * @param {string} path
   * @param {*} value
   */
  AlpineComponent.prototype.set = function (path, value) {
    if (path) setPath(this.scope, path, value);
    else Object.assign(this.scope, value);
    this._walkTree(this.el);
  };

  // ─── Alpine global ─────────────────────────────────────────────────────────────

  const Alpine = {
    version: '3.13.5-csp-jirasnap',
    _components: new Map(),

    /**
     * Start Alpine on all [x-data] elements within root.
     * @param {Element|Document} [root]
     */
    start(root) {
      root = root || document;
      const roots = [];
      if (root.hasAttribute && root.hasAttribute('x-data')) {
        roots.push(/** @type {Element} */ (root));
      }
      if (root.querySelectorAll) {
        Array.from(root.querySelectorAll('[x-data]')).forEach(el => {
          if (!roots.includes(el)) roots.push(el);
        });
      }
      for (const el of roots) {
        if (!this._components.has(el)) {
          const comp = new AlpineComponent(el);
          comp.init();
          this._components.set(el, comp);
        }
      }
    },

    /**
     * Register an Alpine component via Alpine.data().
     * @param {string} name
     * @param {Function} factory
     */
    data(name, factory) {
      // Store factory to be used when x-data="name()" is encountered
      this._factories = this._factories || {};
      this._factories[name] = factory;

      // Patch start() to handle factory-based x-data
      const origStart = this.start.bind(this);
      const self = this;
      this.start = function (root) {
        root = root || document;
        // Handle root element
        if (root.hasAttribute && root.hasAttribute('x-data')) {
          const raw = root.getAttribute('x-data');
          // Is it a factory call? x-data="jiraSnapApp()"
          const match = raw.match(/^(\w+)\(\)$/);
          if (match && self._factories[match[1]]) {
            const comp = new AlpineComponent(root);
            const scope = self._factories[match[1]].call(root);
            comp.scope = scope;
            comp._walkTree(root);
            comp._observe();
            self._components.set(root, comp);
          }
        }
        origStart(root);
      };
    },

    /**
     * Get component for an element.
     * @param {Element} el
     * @returns {AlpineComponent|undefined}
     */
    component(el) {
      return this._components.get(el);
    }
  };

  // ─── Init ──────────────────────────────────────────────────────────────────────

  function go() {
    Alpine.start();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', go);
  } else {
    go();
  }

  global.Alpine = Alpine;

})(window);